void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = texture(iChannel0,fragCoord/iResolution.xy);
}

#define PI 3.1416

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

vec3 hash3(vec2 p)
{
    p*=1000.;
	vec3 p3 = fract(p.xyx * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

float m,it;
float de(vec3 p) {
    vec3 p2=p;
    p.yz*=rot(.3);
    p.xz*=rot(1.);
    p.xz=mod(p.xz,20.)-10.;
    float sc=.08;
    p*=sc;
    p.y+=1.33;
	vec3 pos=p;
    float der=1.;
    m=100.;
    it=0.;
    for(int i=0;i<10;i++){
		p=abs(p)-vec3(0.,2.,0.2);  
        float sc=2./clamp(dot(p,p),0.35,1.);
		p*=sc; 
		der*=sc; 
		p = p - vec3(.5,1.,.5);
		float l=length(p.y);
        if (i<5) m=min(m,l);
        if (m==l) it=float(i);

    }
	float d= (length(p)-4.)/der/sc*.5;
    p2.xz=abs(p2.xz+2.)-2.;
    return d;
}

float det = 0.001;

vec3 normal(vec3 p) {
    vec2 e = vec2(0., det);
    return normalize(vec3(de(p + e.yxx), de(p + e.xyx), de(p + e.xxy)) - de(p));
}

vec3 march(vec3 from, vec3 dir) {
    vec2 uv = gl_FragCoord.xy / iResolution.xy;
    vec3 p = from, col = vec3(0.05);
    float d = .1, maxdist = 100.,bound=45.;
    float choco=0.;
    float h=hash(uv+float(iFrame)*.123)-.5;
    float at=1.;
    for (int b = 0; b < 5; b++) {
        for (int i = 0; i < 100; i++) {
            p += d * dir * (1.+h*.2);
            d = de(p);
            if (d < det || length(p) > bound) break;
        }
        vec3 n = normal(p);
        de(p);
        if (d < det) {
            choco=1.;
            p-=dir*det*2.;
            vec3 r=hash3(uv+float(iFrame)+n.xy+p.xy)-.5; 
            vec3 rs=vec3(vec2(cos(r.x),sin(r.x))*sqrt(1.-r.y*r.y),r.y);
            float rso = dot(n,rs)<0.?-1.:1.;
            vec3 v = rso * rs;
            dir = normalize(v*.5+reflect(dir,n));
            d = det*2.;
            vec3 c=vec3(1.,0.4,0.2);
            c.rb*=rot(-it*.3);
            if (m<.2) col+=c;
            at*=.5;
        }
        vec3 sky=exp(-1.5*(dir.y+.4))*10.*vec3(.3,.5,1.);
        if (length(p) > bound) {
            col+=sky*(.3+choco)*at;
            break;

        }
        col=mix(col,sky*.07,smoothstep(15.,45.,length(p)));
    }
    col*=vec3(1.2,.9,.7);
    return clamp(col,0.,1.);
}

vec2 rand2(vec2 co) {
    return vec2(
        fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453),
        fract(cos(dot(co, vec2(4.898, 7.23))) * 23421.631)
    );
}

vec2 uniformDisc(vec2 co) {
    vec2 r = rand2(co);
    return sqrt(r.y) * vec2(cos(r.x * 6.283185), sin(r.x * 6.283185));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    vec2 pix = 1.5/iResolution.xy;
    uv+=pix*uniformDisc(uv+float(iFrame)*.726);
    vec2 uv2 = fragCoord / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;
    vec3 from = vec3(14., -0.3, -9.);
    vec3 dir = normalize(vec3(uv, 1.1));
    dir.yz*=rot(.25);
    vec3 col = march(from, dir);
    col=pow(col,vec3(1.3));
    col=mix(col,texture(iChannel0,uv2).rgb,1.-exp(-1.5*iTime));
    fragColor = vec4(col, 1.0);
}
